                    },
                    {
                        ["id"] = "neutral.07",
                        ["text"] = {
                            ["EN"] = {
                                "I do not have time for childish games.",
                            },
                            ["TL"] = {
                                "Wala akong panahon sa pambatang laro.",
                            },
