                    {
                        ["id"] = "neutral.01",
                        ["text"] = {
                            ["EN"] = {
                                "I prefer to keep things simple between us.",
                            },
                            ["TL"] = {
                                "Mas gusto kong panatilihing simple ang lahat sa pagitan natin.",
                            },
                        },
                    },
                    {
                        ["id"] = "neutral.02",
                        ["text"] = {
                            ["EN"] = {
                                "Let us just keep this uncomplicated.",
                            },
                            ["TL"] = {
                                "Panatilihin na lang nating hindi magulo ito.",
                            },
                        },
                    },
                    {
                        ["id"] = "neutral.03",
                        ["text"] = {
                            ["EN"] = {
                                "Survival is messy enough without adding that.",
