                    {
                        ["id"] = "neutral.01",
                        ["text"] = {
                            ["EN"] = {
                                "The world changed. I changed with it.",
                            },
                            ["TL"] = {
                                "Nagbago ang mundo. Nagbago rin ako kasabay nito.",
                            },
